import { Mail, Linkedin, Github } from 'lucide-react';

const Contact = () => {
  return (
    <section id="contact" className="py-24 bg-gray-900 text-white px-10">
      <div className="container mx-auto flex flex-col items-center text-center">
        <h2 className="text-5xl md:text-7xl font-black mb-8 tracking-tighter">LET'S CONNECT</h2>
        <p className="text-gray-400 text-lg mb-12 max-w-lg">
          Currently open to Software Intern roles and AI/ML collaborations.
        </p>

        <div className="flex gap-8 mb-16">
          <a href="mailto:agrawalnaitik508@gmail.com" className="hover:text-brand-blue transition-colors"><Mail size={32}/></a>
          <a href="https://www.linkedin.com/in/naitik-agarwal" target="_blank" className="hover:text-brand-blue transition-colors"><Linkedin size={32}/></a>
          <a href="https://github.com/agrawal508" target="_blank" className="hover:text-brand-blue transition-colors"><Github size={32}/></a>
        </div>

        <div className="border-t border-gray-800 pt-8 w-full text-sm text-gray-500">
          © 2026 Naitik Agarwal. Built with React & Tailwind.
        </div>
      </div>
    </section>
  );
};

export default Contact;
